function Stage-ProVolumeCase($Session,$Meta,$Guard){
 $Guard.PinInputFile([string]$Meta.zip);if((Get-FileHash -LiteralPath $Meta.zip).Hash.ToLowerInvariant() -ne $Meta.zipSha256){throw 'Volume payload changed'}
 $archive='C:\MuLab\private\volume-'+$Meta.caseId+'.zip';Copy-Item -LiteralPath $Meta.zip -Destination $archive -ToSession $Session
 return Invoke-Command -Session $Session -ArgumentList $Meta,$archive -ScriptBlock {
  param($meta,$archive)
  $ErrorActionPreference='Stop';$caseId=$meta.caseId;$tools='C:\MuLab\volume-tools\'+$caseId;$configFile='C:\MuLab\approved\volume-'+$caseId+'-config.json';$container='C:\MuLab\private\volume-'+$caseId+'.vhdx'
  if(@(Get-VM).Count -or (Test-Path -LiteralPath $tools) -or (Test-Path -LiteralPath $configFile) -or (Test-Path -LiteralPath $container) -or (Get-Volume -DriveLetter R -ErrorAction SilentlyContinue) -or (Get-Partition -DriveLetter R -ErrorAction SilentlyContinue)){throw 'Fresh empty Pro and unused R drive required'}
  if((Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Transferred volume payload changed'}
  Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive);try{[long]$size=0;if($zip.Entries.Count -gt 12000){throw 'Volume archive count exceeded'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$size+=$entry.Length;if($size -gt 2GB -or $entry.Length -gt 128MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('app/') -and $name -notin @('pro-volume-client.mjs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe volume archive'}}}finally{$zip.Dispose()}
  [IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools);foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Staged volume artifact changed'}}
  $support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$node='C:\MuLab\image-tools\'+$meta.supportCase+'\product\resources\node\node.exe';if((Get-FileHash $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256){throw 'Volume image/runtime changed'}
  $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;if($artifact.sourceDigest -ne $meta.sourceDigest -or (Get-FileHash (Join-Path $bin $artifact.brokerFile)).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Current production broker required'}
  New-VHD -Path $container -Dynamic -SizeBytes 8GB|Out-Null;$mounted=Mount-VHD -Path $container -Passthru;$disk=$mounted|Get-Disk;$backing=Get-VHD -DiskNumber $disk.Number
  if([IO.Path]::GetFullPath($backing.Path) -ne $container -or $backing.ParentPath -or [long]$disk.Size -ne 8GB -or $disk.IsBoot -or $disk.IsSystem -or [string]$disk.PartitionStyle -ne 'RAW'){throw 'Only the exact new standalone 8 GiB diagnostic VHD may be initialized'}
  $disk|Initialize-Disk -PartitionStyle GPT -PassThru|New-Partition -UseMaximumSize -DriveLetter R|Format-Volume -FileSystem NTFS -NewFileSystemLabel ('MuVolume_'+$caseId.Substring(0,8)) -Confirm:$false|Out-Null
  $auxRoot='R:\MuVolume-'+$caseId;[IO.Directory]::CreateDirectory($auxRoot)|Out-Null;$foreign=Join-Path $auxRoot 'foreign.vhdx';New-VHD -Path $foreign -Dynamic -SizeBytes 256GB|Out-Null
  $witness=New-VM -Name ('mu-volume-witness-'+$caseId) -Generation 1 -MemoryStartupBytes 1GB -NoVHD -Path ('C:\MuLab\private\volume-'+$caseId+'-witness');Get-VMNetworkAdapter -VM $witness|Remove-VMNetworkAdapter
  Set-VM -VM $witness -AutomaticStartAction Nothing -AutomaticStopAction TurnOff -CheckpointType Disabled -Notes ('MuCodeSandbox isolated volume witness '+$caseId);Add-VMHardDiskDrive -VM $witness -Path $foreign
  $config=@{caseId=$caseId;proNonce=$meta.proNonce;tools=$tools;app=(Join-Path $tools 'app');node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$meta.imageSha256;files=$meta.files;sourceDigest=$meta.sourceDigest;broker=$artifact;userSid=(Get-LocalUser MuLabUser).SID.Value;container=$container;containerIdentifier=([guid]$backing.DiskIdentifier).ToString('D');diskNumber=[int]$disk.Number;auxRoot=$auxRoot;foreignDisk=$foreign;foreignDiskIdentifier=([guid](Get-VHD $foreign).DiskIdentifier).ToString('D');foreignSha256=(Get-FileHash $foreign).Hash.ToLowerInvariant();witnessId=([guid]$witness.Id).ToString('D')}
  [IO.File]::WriteAllText($configFile,($config|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));return @{complete=$true;caseId=$caseId;staged=$true;auxiliaryDiskGiB=8;foreignVirtualDiskGiB=256;physicalHostDiskFormatted=$false}
 }
}
